/**
 * The colour themes: the curated catalog (docs/notes/theme-slots-1-engine.md) and the
 * user's own (docs/notes/user-themes.md). catalog.json is generated by themes/convert.ts
 * (`pnpm run themes`) and committed: each entry is a theme file (base + overrides). The
 * user's themes are files in the daemon's themes directory, in the same format plus
 * `from` and `created_by`; they arrive on the events stream (stores/themes.ts calls
 * setUserThemes) and are kept in localStorage so a launch on one paints it at once. Both
 * kinds resolve their slots on first use by the rules in ./slots.ts, and lib/theme.ts
 * applies the active theme's slots to <html> as CSS variables.
 */
import catalog from "./catalog.json";
import { componentValues, resolveSlots, type ThemeFile, type ThemeScheme } from "./slots";

export type { ThemeBase, ThemeFile, ThemeScheme } from "./slots";

/** A user theme file as the daemon serves it: a theme file plus where it came from. */
export interface UserThemeFile extends ThemeFile {
  /** The theme it was copied from (curated or user), "" when none. */
  readonly from: string;
  /** The thread that wrote it, "" when the user did or it is unknown. */
  readonly createdBy: string;
  /** Its file in the themes directory. */
  readonly path: string;
}

export interface Theme extends ThemeFile {
  /**
   * Every slot's value: `--cf-*`, `--terminal-*`, `--syn-*` and `--sh-*`, `#rrggbb` or
   * (tints) `#rrggbbaa`. What lib/theme.ts sets on <html> and a ThemeScope on its element.
   */
  readonly slots: Readonly<Record<string, string>>;
  /** The slots plus the component names (`--pane`, `--primary`, ...) as index.css's aliases resolve them. */
  readonly vars: Readonly<Record<string, string>>;
  /** One of the user's themes (the themes directory), not the catalog's. */
  readonly user?: true;
  /** A user theme: the theme it was copied from, "" when none. */
  readonly from?: string;
  /** A user theme: the thread that wrote it, "" when none. */
  readonly createdBy?: string;
}

/** A theme file with its slots resolved once, on first read. */
export function themeOf(file: ThemeFile | UserThemeFile): Theme {
  let slots: Record<string, string> | undefined;
  let vars: Record<string, string> | undefined;
  const user = "from" in file ? { user: true as const, from: file.from, createdBy: file.createdBy } : {};
  return Object.freeze({
    ...file,
    ...user,
    get slots() {
      return (slots ??= resolveSlots(file));
    },
    get vars() {
      const s = (slots ??= resolveSlots(file));
      return (vars ??= { ...s, ...componentValues(s) });
    },
  });
}

/** The curated themes, in catalog order: dark first, the default first in each scheme. */
export const themes: readonly Theme[] = (catalog as ThemeFile[]).map(themeOf);

const curatedIds: ReadonlySet<string> = new Set(themes.map((t) => t.id));

const byId = new Map<string, Theme>(themes.map((t) => [t.id, t]));

/** Every theme by id: the catalog's and the user's (kept current by setUserThemes). */
export const themeById: ReadonlyMap<string, Theme> = byId;

export { DEFAULT_DARK, DEFAULT_LIGHT } from "./defaults";

// ---------------------------------------------------------------- user themes

let user: readonly Theme[] = [];
/** Each user theme's file as JSON, to keep its Theme (and resolved slots) while it is unchanged. */
const userJson = new Map<string, string>();
const listeners = new Set<() => void>();

/** localStorage key of the last user themes, so a launch resolves one before the daemon's list arrives. */
export const USER_THEMES_STORAGE_KEY = "cf.themes.user";

/** The user's themes, by name (as the daemon lists them). */
export function userThemes(): readonly Theme[] {
  return user;
}

/** Calls cb after every change of the user's themes. Returns an unsubscribe. */
export function subscribeUserThemes(cb: () => void): () => void {
  listeners.add(cb);
  return () => {
    listeners.delete(cb);
  };
}

/**
 * Replaces the user's themes. A file whose content is unchanged keeps its Theme object
 * (so the active theme's slots stay the same object and nothing republishes); one with a
 * curated id is ignored (the daemon never lets one in). Listeners run when anything
 * changed.
 */
export function setUserThemes(files: readonly UserThemeFile[], persist = true): void {
  const next: Theme[] = [];
  const seen = new Set<string>();
  let changed = files.length !== user.length;
  for (const [i, f] of files.entries()) {
    if (curatedIds.has(f.id) || seen.has(f.id)) continue;
    seen.add(f.id);
    const json = JSON.stringify(f);
    const prev = byId.get(f.id);
    const keep = prev?.user && userJson.get(f.id) === json ? prev : undefined;
    const t = keep ?? themeOf(f);
    if (!keep) changed = true;
    if (user[i] !== t) changed = true;
    userJson.set(f.id, json);
    next.push(t);
  }
  for (const t of user) {
    if (!seen.has(t.id)) {
      byId.delete(t.id);
      userJson.delete(t.id);
    }
  }
  for (const t of next) byId.set(t.id, t);
  if (!changed) return;
  user = next;
  if (persist) {
    try {
      localStorage.setItem(USER_THEMES_STORAGE_KEY, JSON.stringify(files.filter((f) => seen.has(f.id))));
    } catch {
      // No storage: the next launch shows the default until the daemon's list arrives.
    }
  }
  for (const l of [...listeners]) l();
}

/** The user themes the last launch knew (USER_THEMES_STORAGE_KEY); anything unusable is dropped. */
function storedUserThemes(): UserThemeFile[] {
  try {
    const v: unknown = JSON.parse(localStorage.getItem(USER_THEMES_STORAGE_KEY) ?? "[]");
    if (!Array.isArray(v)) return [];
    return v.filter((f): f is UserThemeFile => {
      if (typeof f !== "object" || f === null) return false;
      const o = f as Record<string, unknown>;
      const base = o.base as Record<string, unknown> | undefined;
      const term = base?.terminal as Record<string, unknown> | undefined;
      return typeof o.id === "string" && typeof o.name === "string" && (o.scheme === "dark" || o.scheme === "light") && typeof o.from === "string" && Array.isArray(term?.ansi);
    });
  } catch {
    return [];
  }
}

setUserThemes(storedUserThemes(), false);

/** The themes that can fill a scheme's slot: the user's (by name), then the catalog's (the default first). */
export function themesFor(scheme: ThemeScheme): readonly Theme[] {
  return [...user.filter((t) => t.scheme === scheme), ...themes.filter((t) => t.scheme === scheme)];
}
